set -euo pipefail
R=/dataset/shaoshitong/search-r1-rl/cosearch
test -z "$(squeue -h --name=cosearch-ranker-probe -o %i)"
test -z "$(squeue -h --name=cosearch-local-five -o %i)"
base64 -d > "$R/tools/gpu-ranker-h.bundle" <<'BUNDLE'

BUNDLE
cd "$R/repo"
git fetch "$R/tools/gpu-ranker-h.bundle" HEAD
git merge --ff-only FETCH_HEAD
cp reproduction/baselines/agent6-20261002/local_gpu_five.py "$R/tools/five_iteration_job_h.py"
cp reproduction/baselines/agent6-20261002/native_gpu_ranker_probe.py "$R/tools/native_gpu_ranker_probe.py"
export OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 PYTHONPATH="$R/tools/test-lib:$R/repo"
"$R/env/bin/python" -m pytest tests/baselines/test_cosearch_batch_parity.py tests/baselines/test_cosearch_fixes.py tests/baselines/test_cosearch_attention.py tests/baselines/test_runtime_audit.py tests/baselines/test_local_runtime.py -q > "$R/logs/gpu-ranker-h-native-tests.log" 2>&1
tail -2 "$R/logs/gpu-ranker-h-native-tests.log"
test ! -d "$R/runs/cosearch-local-gpu-five-20261003-h"
tmux new-session -d -s cosearch-local-gpu-five-h-20261003 "srun --immediate=60 -p gpu -w h100-16 -N1 --ntasks=1 --gres=gpu:h100:8 --exclusive --cpus-per-task=128 --mem=768G --job-name=cosearch-local-five env PYTHONPATH='$R/repo' COSEARCH_RUN_ID=cosearch-local-gpu-five-20261003-h '$R/env/bin/python' -m search_r1.baselines.preflight -- '$R/env/bin/python' '$R/tools/five_iteration_job_h.py' > '$R/logs/local-five-h.log' 2>&1"
